insert into public.reference_projects (id, title, goal_examples, plan) values
  ('blink-led-uno', 'Blinking LED', array['blink an LED', 'my first Arduino project', 'make a light flash', 'hello world Arduino']::text[], '{"title":"Blinking LED","summary":"An LED on pin 13 blinks once per second.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"limits LED current to ~14 mA"},{"ref":"D1","part_id":"led-5mm-red","qty":1,"purpose":"indicator"}],"connections":[{"from":{"ref":"U1","pin":"D13"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND"}}],"steps":["Push the LED into the breadboard; the long leg is the anode (A).","Connect a 220 Ω resistor from Uno pin 13 to the LED anode.","Connect the LED cathode (short leg) to an Uno GND pin.","Plug the Uno into your computer with the USB cable and upload the sketch."],"code":{"filename":"blink.ino","source":"const int LED_PIN = 13;\n\nvoid setup() {\n  pinMode(LED_PIN, OUTPUT);\n}\n\nvoid loop() {\n  digitalWrite(LED_PIN, HIGH);\n  delay(500);\n  digitalWrite(LED_PIN, LOW);\n  delay(500);\n}\n"},"libraries":[],"safety_notes":[],"reference_project_id":"blink-led-uno"}'::jsonb),
  ('button-led-uno', 'Push Button Controls an LED', array['turn on a light with a button', 'button and LED', 'press a button to light an LED']::text[], '{"title":"Push Button Controls an LED","summary":"The LED lights while the button is pressed (internal pull-up, no extra resistor for the button).","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"S1","part_id":"tactile-pushbutton-6mm","qty":1,"purpose":"input"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"LED current limit"},{"ref":"D1","part_id":"led-5mm-green","qty":1,"purpose":"indicator"}],"connections":[{"from":{"ref":"U1","pin":"D2"},"to":{"ref":"S1","pin":"1.l"}},{"from":{"ref":"S1","pin":"2.l"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["Place the button across the breadboard''s middle gap.","Wire one button leg to pin 2 and the diagonal leg to GND.","Wire pin 9 through the 220 Ω resistor to the LED anode; LED cathode to GND.","Upload the sketch and press the button."],"code":{"filename":"button_led.ino","source":"const int BUTTON_PIN = 2;\nconst int LED_PIN = 9;\n\nvoid setup() {\n  pinMode(BUTTON_PIN, INPUT_PULLUP);  // pressed = LOW\n  pinMode(LED_PIN, OUTPUT);\n}\n\nvoid loop() {\n  bool pressed = digitalRead(BUTTON_PIN) == LOW;\n  digitalWrite(LED_PIN, pressed ? HIGH : LOW);\n}\n"},"libraries":[],"safety_notes":[],"reference_project_id":"button-led-uno"}'::jsonb),
  ('traffic-light-uno', 'Traffic Light', array['traffic light', 'red yellow green LEDs', 'make a stop light']::text[], '{"title":"Traffic Light","summary":"Three LEDs cycle red → green → yellow like a traffic light.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"red LED resistor"},{"ref":"R2","part_id":"resistor-220","qty":1,"purpose":"yellow LED resistor"},{"ref":"R3","part_id":"resistor-220","qty":1,"purpose":"green LED resistor"},{"ref":"D1","part_id":"led-5mm-red","qty":1,"purpose":"stop"},{"ref":"D2","part_id":"led-5mm-yellow","qty":1,"purpose":"caution"},{"ref":"D3","part_id":"led-5mm-green","qty":1,"purpose":"go"}],"connections":[{"from":{"ref":"U1","pin":"D10"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"R2","pin":"1"}},{"from":{"ref":"R2","pin":"2"},"to":{"ref":"D2","pin":"A"}},{"from":{"ref":"D2","pin":"C"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"R3","pin":"1"}},{"from":{"ref":"R3","pin":"2"},"to":{"ref":"D3","pin":"A"}},{"from":{"ref":"D3","pin":"C"},"to":{"ref":"U1","pin":"GND"}}],"steps":["Place the red, yellow and green LEDs in a column on the breadboard.","Connect pins 10, 9 and 8 through a 220 Ω resistor each to the red, yellow and green anodes.","Connect all three cathodes to GND.","Upload the sketch."],"code":{"filename":"traffic_light.ino","source":"const int RED = 10, YELLOW = 9, GREEN = 8;\n\nvoid show(int r, int y, int g, unsigned long ms) {\n  digitalWrite(RED, r);\n  digitalWrite(YELLOW, y);\n  digitalWrite(GREEN, g);\n  delay(ms);\n}\n\nvoid setup() {\n  pinMode(RED, OUTPUT);\n  pinMode(YELLOW, OUTPUT);\n  pinMode(GREEN, OUTPUT);\n}\n\nvoid loop() {\n  show(HIGH, LOW, LOW, 4000);\n  show(LOW, LOW, HIGH, 4000);\n  show(LOW, HIGH, LOW, 1500);\n}\n"},"libraries":[],"safety_notes":[],"reference_project_id":"traffic-light-uno"}'::jsonb),
  ('ultrasonic-distance-uno', 'Ultrasonic Distance Meter', array['measure distance', 'ultrasonic sensor', 'how far away is something', 'HC-SR04 project']::text[], '{"title":"Ultrasonic Distance Meter","summary":"Prints the distance to the nearest object in centimetres to the Serial Monitor.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"hc-sr04-ultrasonic","qty":1,"purpose":"distance sensor"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U1","pin":"GND"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"U2","pin":"TRIG"}},{"from":{"ref":"U1","pin":"D10"},"to":{"ref":"U2","pin":"ECHO"}}],"steps":["Connect HC-SR04 VCC to 5V and GND to GND.","Connect TRIG to pin 9 and ECHO to pin 10.","Upload the sketch and open the Serial Monitor at 9600 baud."],"code":{"filename":"distance.ino","source":"const int TRIG = 9, ECHO = 10;\n\nvoid setup() {\n  pinMode(TRIG, OUTPUT);\n  pinMode(ECHO, INPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  digitalWrite(TRIG, LOW);\n  delayMicroseconds(2);\n  digitalWrite(TRIG, HIGH);\n  delayMicroseconds(10);\n  digitalWrite(TRIG, LOW);\n  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);\n  if (us == 0) {\n    Serial.println(\"out of range\");\n  } else {\n    Serial.print(us / 58.0, 1);\n    Serial.println(\" cm\");\n  }\n  delay(200);\n}\n"},"libraries":[],"safety_notes":[],"reference_project_id":"ultrasonic-distance-uno"}'::jsonb),
  ('servo-sweep-uno', 'Servo Sweep', array['move a servo', 'servo motor back and forth', 'sweep a servo']::text[], '{"title":"Servo Sweep","summary":"An SG90 servo sweeps from 0° to 180° and back.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"M1","part_id":"sg90-micro-servo","qty":1,"purpose":"actuator"}],"connections":[{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"M1","pin":"PWM"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"M1","pin":"V+"}},{"from":{"ref":"U1","pin":"GND"},"to":{"ref":"M1","pin":"GND"}}],"steps":["Connect the servo''s brown wire to GND, red to 5V and orange (signal) to pin 9.","Upload the sketch."],"code":{"filename":"servo_sweep.ino","source":"#include <Servo.h>\n\nServo servo;\n\nvoid setup() {\n  servo.attach(9);\n}\n\nvoid loop() {\n  for (int a = 0; a <= 180; a++) { servo.write(a); delay(15); }\n  for (int a = 180; a >= 0; a--) { servo.write(a); delay(15); }\n}\n"},"libraries":[{"name":"Servo","install_hint":"Built into the Arduino IDE"}],"safety_notes":["Keep fingers away from the servo horn while it moves."],"reference_project_id":"servo-sweep-uno"}'::jsonb),
  ('pot-servo-uno', 'Knob-Controlled Servo', array['control a servo with a knob', 'potentiometer servo', 'turn a dial to move a motor']::text[], '{"title":"Knob-Controlled Servo","summary":"Turning the potentiometer sets the servo angle.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"RV1","part_id":"potentiometer-10k","qty":1,"purpose":"angle input"},{"ref":"M1","part_id":"sg90-micro-servo","qty":1,"purpose":"actuator"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"RV1","pin":"VCC"}},{"from":{"ref":"RV1","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"RV1","pin":"SIG"},"to":{"ref":"U1","pin":"A0"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"M1","pin":"PWM"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"M1","pin":"V+"}},{"from":{"ref":"U1","pin":"GND.2"},"to":{"ref":"M1","pin":"GND"}}],"steps":["Connect the potentiometer''s outer legs to 5V and GND and its middle leg to A0.","Connect the servo signal to pin 9, red to 5V, brown to GND.","Upload the sketch and turn the knob."],"code":{"filename":"knob_servo.ino","source":"#include <Servo.h>\n\nServo servo;\n\nvoid setup() {\n  servo.attach(9);\n}\n\nvoid loop() {\n  int raw = analogRead(A0);\n  servo.write(map(raw, 0, 1023, 0, 180));\n  delay(15);\n}\n"},"libraries":[{"name":"Servo","install_hint":"Built into the Arduino IDE"}],"safety_notes":[],"reference_project_id":"pot-servo-uno"}'::jsonb),
  ('night-light-ldr-uno', 'Automatic Night Light', array['light turns on when dark', 'night light', 'light sensor LED', 'photoresistor project']::text[], '{"title":"Automatic Night Light","summary":"An LED turns on when the photoresistor reads darkness.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"LDR1","part_id":"ldr-photoresistor-gl5528","qty":1,"purpose":"light sensor"},{"ref":"R1","part_id":"resistor-10k","qty":1,"purpose":"divider with the LDR"},{"ref":"R2","part_id":"resistor-220","qty":1,"purpose":"LED current limit"},{"ref":"D1","part_id":"led-5mm-white","qty":1,"purpose":"light"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"LDR1","pin":"1"}},{"from":{"ref":"LDR1","pin":"2"},"to":{"ref":"U1","pin":"A0"}},{"from":{"ref":"U1","pin":"A0"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"R2","pin":"1"}},{"from":{"ref":"R2","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["Connect the photoresistor between 5V and A0.","Connect a 10 kΩ resistor between A0 and GND (voltage divider).","Connect pin 9 through 220 Ω to the LED anode and the cathode to GND.","Upload the sketch; cover the sensor to switch the light on."],"code":{"filename":"night_light.ino","source":"const int SENSOR = A0, LED = 9;\nconst int DARK_THRESHOLD = 300;  // lower = darker; tune for your room\n\nvoid setup() {\n  pinMode(LED, OUTPUT);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int light = analogRead(SENSOR);\n  Serial.println(light);\n  digitalWrite(LED, light < DARK_THRESHOLD ? HIGH : LOW);\n  delay(100);\n}\n"},"libraries":[],"safety_notes":[],"reference_project_id":"night-light-ldr-uno"}'::jsonb),
  ('parking-sensor-uno', 'Parking Sensor', array['parking sensor', 'beep when something is close', 'distance alarm with buzzer']::text[], '{"title":"Parking Sensor","summary":"Beeps faster and switches from green to red as an object gets closer.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"hc-sr04-ultrasonic","qty":1,"purpose":"distance sensor"},{"ref":"BZ1","part_id":"buzzer-passive-piezo","qty":1,"purpose":"beeper"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"green LED resistor"},{"ref":"R2","part_id":"resistor-220","qty":1,"purpose":"red LED resistor"},{"ref":"D1","part_id":"led-5mm-green","qty":1,"purpose":"far"},{"ref":"D2","part_id":"led-5mm-red","qty":1,"purpose":"close"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U1","pin":"GND"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"U2","pin":"TRIG"}},{"from":{"ref":"U1","pin":"D10"},"to":{"ref":"U2","pin":"ECHO"}},{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"BZ1","pin":"+"}},{"from":{"ref":"BZ1","pin":"-"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D4"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D5"},"to":{"ref":"R2","pin":"1"}},{"from":{"ref":"R2","pin":"2"},"to":{"ref":"D2","pin":"A"}},{"from":{"ref":"D2","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["Wire the HC-SR04: VCC→5V, GND→GND, TRIG→9, ECHO→10.","Connect the buzzer + to pin 8 and − to GND.","Connect the green LED (via 220 Ω) to pin 4 and the red LED (via 220 Ω) to pin 5.","Upload the sketch and move your hand toward the sensor."],"code":{"filename":"parking_sensor.ino","source":"const int TRIG = 9, ECHO = 10, BUZZER = 8, GREEN = 4, RED = 5;\n\nlong readCm() {\n  digitalWrite(TRIG, LOW); delayMicroseconds(2);\n  digitalWrite(TRIG, HIGH); delayMicroseconds(10);\n  digitalWrite(TRIG, LOW);\n  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);\n  return us == 0 ? 999 : us / 58;\n}\n\nvoid setup() {\n  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);\n  pinMode(GREEN, OUTPUT); pinMode(RED, OUTPUT);\n}\n\nvoid loop() {\n  long cm = readCm();\n  bool close = cm < 30;\n  digitalWrite(GREEN, close ? LOW : HIGH);\n  digitalWrite(RED, close ? HIGH : LOW);\n  if (cm < 100) {\n    tone(BUZZER, 2000, 50);\n    delay(constrain(cm * 8, 60, 800));\n  } else {\n    delay(100);\n  }\n}\n"},"libraries":[],"safety_notes":[],"reference_project_id":"parking-sensor-uno"}'::jsonb),
  ('pir-alarm-uno', 'Motion Alarm', array['motion detector alarm', 'detect people', 'PIR sensor alarm', 'intruder alarm']::text[], '{"title":"Motion Alarm","summary":"A PIR sensor triggers a beep and a red LED when motion is detected.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"hc-sr501-pir","qty":1,"purpose":"motion sensor"},{"ref":"BZ1","part_id":"buzzer-passive-piezo","qty":1,"purpose":"alarm"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"LED resistor"},{"ref":"D1","part_id":"led-5mm-red","qty":1,"purpose":"alarm light"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"OUT"},"to":{"ref":"U1","pin":"D2"}},{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"BZ1","pin":"+"}},{"from":{"ref":"BZ1","pin":"-"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D13"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["Connect the PIR VCC to 5V, GND to GND and OUT to pin 2.","Connect the buzzer + to pin 8 and − to GND.","Connect pin 13 via 220 Ω to the red LED.","Upload, then wait ~30 s for the PIR to settle."],"code":{"filename":"motion_alarm.ino","source":"const int PIR = 2, BUZZER = 8, LED = 13;\n\nvoid setup() {\n  pinMode(PIR, INPUT);\n  pinMode(LED, OUTPUT);\n}\n\nvoid loop() {\n  if (digitalRead(PIR) == HIGH) {\n    digitalWrite(LED, HIGH);\n    tone(BUZZER, 1500, 200);\n    delay(300);\n  } else {\n    digitalWrite(LED, LOW);\n  }\n}\n"},"libraries":[],"safety_notes":[],"reference_project_id":"pir-alarm-uno"}'::jsonb),
  ('ir-remote-led-uno', 'IR Remote Light Switch', array['control LEDs with a TV remote', 'IR remote project', 'infrared remote control']::text[], '{"title":"IR Remote Light Switch","summary":"Buttons 1 and 2 on an IR remote toggle two LEDs.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"ir-receiver-vs1838b","qty":1,"purpose":"IR receiver"},{"ref":"RC1","part_id":"ir-remote-nec-21key","qty":1,"purpose":"remote"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"LED resistor"},{"ref":"R2","part_id":"resistor-220","qty":1,"purpose":"LED resistor"},{"ref":"D1","part_id":"led-5mm-red","qty":1,"purpose":"light 1"},{"ref":"D2","part_id":"led-5mm-blue","qty":1,"purpose":"light 2"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"OUT"},"to":{"ref":"U1","pin":"D11"}},{"from":{"ref":"U1","pin":"D4"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D5"},"to":{"ref":"R2","pin":"1"}},{"from":{"ref":"R2","pin":"2"},"to":{"ref":"D2","pin":"A"}},{"from":{"ref":"D2","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["Connect the IR receiver: VCC→5V, GND→GND, OUT→pin 11.","Connect two LEDs through 220 Ω resistors to pins 4 and 5.","Install the IRremote library, upload, and press 1 or 2 on the remote."],"code":{"filename":"ir_lights.ino","source":"#include <IRremote.hpp>\n\nconst int IR_PIN = 11, LED1 = 4, LED2 = 5;\nbool on1 = false, on2 = false;\n\nvoid setup() {\n  pinMode(LED1, OUTPUT);\n  pinMode(LED2, OUTPUT);\n  IrReceiver.begin(IR_PIN, DISABLE_LED_FEEDBACK);\n}\n\nvoid loop() {\n  if (!IrReceiver.decode()) return;\n  uint8_t cmd = IrReceiver.decodedIRData.command;\n  IrReceiver.resume();\n  if (cmd == 0x0C) { on1 = !on1; digitalWrite(LED1, on1); }   // button 1\n  if (cmd == 0x18) { on2 = !on2; digitalWrite(LED2, on2); }   // button 2\n}\n"},"libraries":[{"name":"IRremote","install_hint":"Library Manager: IRremote by shirriff/z3t0/ArminJo (v4)"}],"safety_notes":[],"reference_project_id":"ir-remote-led-uno"}'::jsonb),
  ('rc-car-bluetooth-uno', 'Bluetooth RC Car', array['Can I build an RC car?', 'remote control car', 'control a car from my phone', 'bluetooth car', 'build a robot car I can drive']::text[], '{"title":"Bluetooth RC Car","summary":"A two-wheel car you drive from a phone app over Bluetooth (HC-05).","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"battery","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"l298n-motor-driver","qty":1,"purpose":"drives both motors"},{"ref":"M1","part_id":"tt-dc-gear-motor","qty":1,"purpose":"left wheel"},{"ref":"M2","part_id":"tt-dc-gear-motor","qty":1,"purpose":"right wheel"},{"ref":"B1","part_id":"battery-holder-2x18650","qty":1,"purpose":"7.4 V power for motors and Uno"},{"ref":"X1","part_id":"robot-car-chassis-2wd","qty":1,"purpose":"frame and wheels"},{"ref":"W1","part_id":"jumper-wires-male-female","qty":1,"purpose":"wiring"},{"ref":"U3","part_id":"hc-05-bluetooth","qty":1,"purpose":"Bluetooth link to the phone"},{"ref":"DIV1","part_id":"voltage-divider-5v-3v3","qty":1,"purpose":"drops Uno TX (5 V) to 3.3 V for HC-05 RXD"}],"connections":[{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U2","pin":"12V"}},{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U1","pin":"VIN"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D5"},"to":{"ref":"U2","pin":"ENA"}},{"from":{"ref":"U1","pin":"D7"},"to":{"ref":"U2","pin":"IN1"}},{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"U2","pin":"IN2"}},{"from":{"ref":"U1","pin":"D11"},"to":{"ref":"U2","pin":"IN3"}},{"from":{"ref":"U1","pin":"D12"},"to":{"ref":"U2","pin":"IN4"}},{"from":{"ref":"U1","pin":"D6"},"to":{"ref":"U2","pin":"ENB"}},{"from":{"ref":"U2","pin":"OUT1"},"to":{"ref":"M1","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT2"},"to":{"ref":"M1","pin":"M-"}},{"from":{"ref":"U2","pin":"OUT3"},"to":{"ref":"M2","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT4"},"to":{"ref":"M2","pin":"M-"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U1","pin":"GND.2"},"to":{"ref":"U3","pin":"GND"}},{"from":{"ref":"U3","pin":"TXD"},"to":{"ref":"U1","pin":"D2"}},{"from":{"ref":"U1","pin":"D3"},"to":{"ref":"DIV1","pin":"IN"}},{"from":{"ref":"DIV1","pin":"OUT"},"to":{"ref":"U3","pin":"RXD"}},{"from":{"ref":"DIV1","pin":"GND"},"to":{"ref":"U1","pin":"GND.3"}}],"steps":["Screw the two TT motors, wheels and caster onto the chassis.","Mount the Uno, the L298N and the 2×18650 battery holder on the chassis.","Wire the left motor to L298N OUT1/OUT2 and the right motor to OUT3/OUT4.","Battery + to L298N 12V and to Uno VIN; battery − to L298N GND, and L298N GND to Uno GND (common ground).","Remove the ENA/ENB jumpers on the L298N, then wire ENA→5, IN1→7, IN2→8, IN3→11, IN4→12, ENB→6.","HC-05: VCC→5V, GND→GND, TXD→pin 2.","Make the divider: pin 3 → 1 kΩ → junction → 2 kΩ → GND; connect the junction to HC-05 RXD.","Upload the sketch with the battery switched off, then switch it on.","Pair the phone with HC-05 (PIN 1234) and use any ''Bluetooth RC controller'' app that sends F/B/L/R/S."],"code":{"filename":"bluetooth_car.ino","source":"#include <SoftwareSerial.h>\n\nSoftwareSerial bt(2, 3);  // RX, TX (TX goes through the divider)\nconst int ENA = 5, IN1 = 7, IN2 = 8, IN3 = 11, IN4 = 12, ENB = 6;\n\nvoid drive(int l1, int l2, int r1, int r2) {\n  digitalWrite(IN1, l1); digitalWrite(IN2, l2);\n  digitalWrite(IN3, r1); digitalWrite(IN4, r2);\n}\nvoid forward()  { drive(HIGH, LOW, HIGH, LOW); }\nvoid backward() { drive(LOW, HIGH, LOW, HIGH); }\nvoid left()     { drive(LOW, HIGH, HIGH, LOW); }\nvoid right()    { drive(HIGH, LOW, LOW, HIGH); }\nvoid stopCar()  { drive(LOW, LOW, LOW, LOW); }\n\nvoid setupMotors(int speed) {\n  int pins[] = {ENA, IN1, IN2, IN3, IN4, ENB};\n  for (int p : pins) pinMode(p, OUTPUT);\n  analogWrite(ENA, speed);\n  analogWrite(ENB, speed);\n  stopCar();\n}\n\nvoid setup() {\n  setupMotors(200);\n  bt.begin(9600);\n}\n\nvoid loop() {\n  if (!bt.available()) return;\n  switch (bt.read()) {\n    case ''F'': forward(); break;\n    case ''B'': backward(); break;\n    case ''L'': left(); break;\n    case ''R'': right(); break;\n    default: stopCar(); break;\n  }\n}\n"},"libraries":[{"name":"SoftwareSerial","install_hint":"Built into the Arduino IDE"}],"safety_notes":["Use protected 18650 cells, insert them with the correct polarity, and never short the battery leads.","Lift the wheels off the table for the first test."],"reference_project_id":"rc-car-bluetooth-uno"}'::jsonb),
  ('rc-car-ir-remote-uno', 'IR Remote-Controlled Car', array['RC car with a remote', 'car controlled by TV remote', 'infrared remote car']::text[], '{"title":"IR Remote-Controlled Car","summary":"A two-wheel car driven with the number keys of a 21-key IR remote.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"battery","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"l298n-motor-driver","qty":1,"purpose":"drives both motors"},{"ref":"M1","part_id":"tt-dc-gear-motor","qty":1,"purpose":"left wheel"},{"ref":"M2","part_id":"tt-dc-gear-motor","qty":1,"purpose":"right wheel"},{"ref":"B1","part_id":"battery-holder-2x18650","qty":1,"purpose":"7.4 V power for motors and Uno"},{"ref":"X1","part_id":"robot-car-chassis-2wd","qty":1,"purpose":"frame and wheels"},{"ref":"W1","part_id":"jumper-wires-male-female","qty":1,"purpose":"wiring"},{"ref":"U3","part_id":"ir-receiver-vs1838b","qty":1,"purpose":"IR receiver"},{"ref":"RC1","part_id":"ir-remote-nec-21key","qty":1,"purpose":"remote"}],"connections":[{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U2","pin":"12V"}},{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U1","pin":"VIN"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D5"},"to":{"ref":"U2","pin":"ENA"}},{"from":{"ref":"U1","pin":"D7"},"to":{"ref":"U2","pin":"IN1"}},{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"U2","pin":"IN2"}},{"from":{"ref":"U1","pin":"D11"},"to":{"ref":"U2","pin":"IN3"}},{"from":{"ref":"U1","pin":"D12"},"to":{"ref":"U2","pin":"IN4"}},{"from":{"ref":"U1","pin":"D6"},"to":{"ref":"U2","pin":"ENB"}},{"from":{"ref":"U2","pin":"OUT1"},"to":{"ref":"M1","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT2"},"to":{"ref":"M1","pin":"M-"}},{"from":{"ref":"U2","pin":"OUT3"},"to":{"ref":"M2","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT4"},"to":{"ref":"M2","pin":"M-"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U3","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U3","pin":"OUT"},"to":{"ref":"U1","pin":"D2"}}],"steps":["Screw the two TT motors, wheels and caster onto the chassis.","Mount the Uno, the L298N and the 2×18650 battery holder on the chassis.","Wire the left motor to L298N OUT1/OUT2 and the right motor to OUT3/OUT4.","Battery + to L298N 12V and to Uno VIN; battery − to L298N GND, and L298N GND to Uno GND (common ground).","Remove the ENA/ENB jumpers on the L298N, then wire ENA→5, IN1→7, IN2→8, IN3→11, IN4→12, ENB→6.","IR receiver: VCC→5V, GND→GND, OUT→pin 2; face it forward.","Upload the sketch; use 2/8/4/6 to drive and 5 to stop."],"code":{"filename":"ir_car.ino","source":"#include <IRremote.hpp>\nconst int ENA = 5, IN1 = 7, IN2 = 8, IN3 = 11, IN4 = 12, ENB = 6;\n\nvoid drive(int l1, int l2, int r1, int r2) {\n  digitalWrite(IN1, l1); digitalWrite(IN2, l2);\n  digitalWrite(IN3, r1); digitalWrite(IN4, r2);\n}\nvoid forward()  { drive(HIGH, LOW, HIGH, LOW); }\nvoid backward() { drive(LOW, HIGH, LOW, HIGH); }\nvoid left()     { drive(LOW, HIGH, HIGH, LOW); }\nvoid right()    { drive(HIGH, LOW, LOW, HIGH); }\nvoid stopCar()  { drive(LOW, LOW, LOW, LOW); }\n\nvoid setupMotors(int speed) {\n  int pins[] = {ENA, IN1, IN2, IN3, IN4, ENB};\n  for (int p : pins) pinMode(p, OUTPUT);\n  analogWrite(ENA, speed);\n  analogWrite(ENB, speed);\n  stopCar();\n}\n\nvoid setup() {\n  setupMotors(200);\n  IrReceiver.begin(2, DISABLE_LED_FEEDBACK);\n}\n\nvoid loop() {\n  if (!IrReceiver.decode()) return;\n  uint8_t cmd = IrReceiver.decodedIRData.command;\n  IrReceiver.resume();\n  switch (cmd) {\n    case 0x18: forward(); break;   // 2\n    case 0x52: backward(); break;  // 8\n    case 0x08: left(); break;      // 4\n    case 0x5A: right(); break;     // 6\n    case 0x1C: stopCar(); break;   // 5\n  }\n}\n"},"libraries":[{"name":"IRremote","install_hint":"Library Manager: IRremote (v4)"}],"safety_notes":["Use protected 18650 cells, insert them with the correct polarity, and never short the battery leads.","Lift the wheels off the table for the first test."],"reference_project_id":"rc-car-ir-remote-uno"}'::jsonb),
  ('rc-car-wifi-esp32', 'Wi-Fi RC Car (ESP32)', array['wifi car', 'car controlled from a web page', 'ESP32 RC car', 'drive a car from my browser']::text[], '{"title":"Wi-Fi RC Car (ESP32)","summary":"The ESP32 creates a Wi-Fi hotspot with a web page to drive the car.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"battery","parts":[{"ref":"U1","part_id":"esp32-devkit-v1","qty":1,"purpose":"controller + Wi-Fi"},{"ref":"U2","part_id":"l298n-motor-driver","qty":1,"purpose":"drives both motors"},{"ref":"M1","part_id":"tt-dc-gear-motor","qty":1,"purpose":"left wheel"},{"ref":"M2","part_id":"tt-dc-gear-motor","qty":1,"purpose":"right wheel"},{"ref":"B1","part_id":"battery-holder-2x18650","qty":1,"purpose":"7.4 V power for motors and Uno"},{"ref":"X1","part_id":"robot-car-chassis-2wd","qty":1,"purpose":"frame and wheels"},{"ref":"W1","part_id":"jumper-wires-male-female","qty":1,"purpose":"wiring"}],"connections":[{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U2","pin":"12V"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"U2","pin":"5V"},"to":{"ref":"U1","pin":"VIN"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D13"},"to":{"ref":"U2","pin":"ENA"}},{"from":{"ref":"U1","pin":"D27"},"to":{"ref":"U2","pin":"IN1"}},{"from":{"ref":"U1","pin":"D26"},"to":{"ref":"U2","pin":"IN2"}},{"from":{"ref":"U1","pin":"D25"},"to":{"ref":"U2","pin":"IN3"}},{"from":{"ref":"U1","pin":"D33"},"to":{"ref":"U2","pin":"IN4"}},{"from":{"ref":"U1","pin":"D32"},"to":{"ref":"U2","pin":"ENB"}},{"from":{"ref":"U2","pin":"OUT1"},"to":{"ref":"M1","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT2"},"to":{"ref":"M1","pin":"M-"}},{"from":{"ref":"U2","pin":"OUT3"},"to":{"ref":"M2","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT4"},"to":{"ref":"M2","pin":"M-"}}],"steps":["Assemble the chassis with both motors and mount the ESP32, L298N and battery holder.","Motors to OUT1/OUT2 and OUT3/OUT4.","Battery + to L298N 12V, battery − to L298N GND; L298N 5V to ESP32 VIN and L298N GND to ESP32 GND.","Remove the ENA/ENB jumpers and wire ENA→D13, IN1→D27, IN2→D26, IN3→D25, IN4→D33, ENB→D32.","Upload over USB with the battery off. Then power on, join Wi-Fi ''PartsPilot-Car'' (password drive1234) and open 192.168.4.1."],"code":{"filename":"wifi_car.ino","source":"#include <WiFi.h>\n#include <WebServer.h>\n\nconst int ENA = 13, IN1 = 27, IN2 = 26, IN3 = 25, IN4 = 33, ENB = 32;\nWebServer server(80);\n\nconst char PAGE[] = R\"html(<!doctype html><meta name=viewport content=\"width=device-width\">\n<style>a{display:inline-block;padding:24px;margin:6px;background:#246;color:#fff;font:24px sans-serif;text-decoration:none}</style>\n<a href=/f>Forward</a><br><a href=/l>Left</a><a href=/s>Stop</a><a href=/r>Right</a><br><a href=/b>Back</a>)html\";\n\nvoid drive(int a, int b, int c, int d) {\n  digitalWrite(IN1, a); digitalWrite(IN2, b); digitalWrite(IN3, c); digitalWrite(IN4, d);\n}\n\nvoid reply(int a, int b, int c, int d) {\n  drive(a, b, c, d);\n  server.send(200, \"text/html\", PAGE);\n}\n\nvoid setup() {\n  int pins[] = {IN1, IN2, IN3, IN4};\n  for (int p : pins) pinMode(p, OUTPUT);\n  ledcAttach(ENA, 1000, 8);   // ESP32 Arduino core 3.x\n  ledcAttach(ENB, 1000, 8);\n  ledcWrite(ENA, 200);\n  ledcWrite(ENB, 200);\n  WiFi.softAP(\"PartsPilot-Car\", \"drive1234\");\n  server.on(\"/\", [] { reply(LOW, LOW, LOW, LOW); });\n  server.on(\"/s\", [] { reply(LOW, LOW, LOW, LOW); });\n  server.on(\"/f\", [] { reply(HIGH, LOW, HIGH, LOW); });\n  server.on(\"/b\", [] { reply(LOW, HIGH, LOW, HIGH); });\n  server.on(\"/l\", [] { reply(LOW, HIGH, HIGH, LOW); });\n  server.on(\"/r\", [] { reply(HIGH, LOW, LOW, HIGH); });\n  server.begin();\n}\n\nvoid loop() {\n  server.handleClient();\n}\n"},"libraries":[{"name":"ESP32 board package 3.x","install_hint":"Boards Manager: esp32 by Espressif Systems"}],"safety_notes":["Use protected 18650 cells, insert them with the correct polarity, and never short the battery leads.","Lift the wheels off the table for the first test."],"reference_project_id":"rc-car-wifi-esp32"}'::jsonb),
  ('obstacle-avoiding-robot-uno', 'Obstacle-Avoiding Robot', array['robot that avoids walls', 'self driving robot', 'obstacle avoiding car', 'autonomous robot']::text[], '{"title":"Obstacle-Avoiding Robot","summary":"Drives forward and turns away when the ultrasonic sensor sees an obstacle closer than 20 cm.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"battery","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"l298n-motor-driver","qty":1,"purpose":"drives both motors"},{"ref":"M1","part_id":"tt-dc-gear-motor","qty":1,"purpose":"left wheel"},{"ref":"M2","part_id":"tt-dc-gear-motor","qty":1,"purpose":"right wheel"},{"ref":"B1","part_id":"battery-holder-2x18650","qty":1,"purpose":"7.4 V power for motors and Uno"},{"ref":"X1","part_id":"robot-car-chassis-2wd","qty":1,"purpose":"frame and wheels"},{"ref":"W1","part_id":"jumper-wires-male-female","qty":1,"purpose":"wiring"},{"ref":"U3","part_id":"hc-sr04-ultrasonic","qty":1,"purpose":"obstacle sensor"}],"connections":[{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U2","pin":"12V"}},{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U1","pin":"VIN"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D5"},"to":{"ref":"U2","pin":"ENA"}},{"from":{"ref":"U1","pin":"D7"},"to":{"ref":"U2","pin":"IN1"}},{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"U2","pin":"IN2"}},{"from":{"ref":"U1","pin":"D11"},"to":{"ref":"U2","pin":"IN3"}},{"from":{"ref":"U1","pin":"D12"},"to":{"ref":"U2","pin":"IN4"}},{"from":{"ref":"U1","pin":"D6"},"to":{"ref":"U2","pin":"ENB"}},{"from":{"ref":"U2","pin":"OUT1"},"to":{"ref":"M1","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT2"},"to":{"ref":"M1","pin":"M-"}},{"from":{"ref":"U2","pin":"OUT3"},"to":{"ref":"M2","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT4"},"to":{"ref":"M2","pin":"M-"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U3","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"U3","pin":"TRIG"}},{"from":{"ref":"U1","pin":"D10"},"to":{"ref":"U3","pin":"ECHO"}}],"steps":["Screw the two TT motors, wheels and caster onto the chassis.","Mount the Uno, the L298N and the 2×18650 battery holder on the chassis.","Wire the left motor to L298N OUT1/OUT2 and the right motor to OUT3/OUT4.","Battery + to L298N 12V and to Uno VIN; battery − to L298N GND, and L298N GND to Uno GND (common ground).","Remove the ENA/ENB jumpers on the L298N, then wire ENA→5, IN1→7, IN2→8, IN3→11, IN4→12, ENB→6.","Mount the HC-SR04 at the front: VCC→5V, GND→GND, TRIG→9, ECHO→10.","Upload with the battery off, then switch on and let it roam."],"code":{"filename":"obstacle_robot.ino","source":"const int ENA = 5, IN1 = 7, IN2 = 8, IN3 = 11, IN4 = 12, ENB = 6;\n\nvoid drive(int l1, int l2, int r1, int r2) {\n  digitalWrite(IN1, l1); digitalWrite(IN2, l2);\n  digitalWrite(IN3, r1); digitalWrite(IN4, r2);\n}\nvoid forward()  { drive(HIGH, LOW, HIGH, LOW); }\nvoid backward() { drive(LOW, HIGH, LOW, HIGH); }\nvoid left()     { drive(LOW, HIGH, HIGH, LOW); }\nvoid right()    { drive(HIGH, LOW, LOW, HIGH); }\nvoid stopCar()  { drive(LOW, LOW, LOW, LOW); }\n\nvoid setupMotors(int speed) {\n  int pins[] = {ENA, IN1, IN2, IN3, IN4, ENB};\n  for (int p : pins) pinMode(p, OUTPUT);\n  analogWrite(ENA, speed);\n  analogWrite(ENB, speed);\n  stopCar();\n}\n\nconst int TRIG = 9, ECHO = 10;\n\nlong readCm() {\n  digitalWrite(TRIG, LOW); delayMicroseconds(2);\n  digitalWrite(TRIG, HIGH); delayMicroseconds(10);\n  digitalWrite(TRIG, LOW);\n  unsigned long us = pulseIn(ECHO, HIGH, 30000UL);\n  return us == 0 ? 999 : us / 58;\n}\n\nvoid setup() {\n  setupMotors(170);\n  pinMode(TRIG, OUTPUT);\n  pinMode(ECHO, INPUT);\n}\n\nvoid loop() {\n  if (readCm() < 20) {\n    stopCar(); delay(200);\n    backward(); delay(400);\n    right(); delay(350);\n  } else {\n    forward();\n  }\n  delay(50);\n}\n"},"libraries":[],"safety_notes":["Use protected 18650 cells, insert them with the correct polarity, and never short the battery leads.","Lift the wheels off the table for the first test."],"reference_project_id":"obstacle-avoiding-robot-uno"}'::jsonb),
  ('line-follower-uno', 'Line-Following Robot', array['line follower robot', 'robot follows a black line', 'track following car']::text[], '{"title":"Line-Following Robot","summary":"Two IR sensors keep the car on a black tape line.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"battery","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"l298n-motor-driver","qty":1,"purpose":"drives both motors"},{"ref":"M1","part_id":"tt-dc-gear-motor","qty":1,"purpose":"left wheel"},{"ref":"M2","part_id":"tt-dc-gear-motor","qty":1,"purpose":"right wheel"},{"ref":"B1","part_id":"battery-holder-2x18650","qty":1,"purpose":"7.4 V power for motors and Uno"},{"ref":"X1","part_id":"robot-car-chassis-2wd","qty":1,"purpose":"frame and wheels"},{"ref":"W1","part_id":"jumper-wires-male-female","qty":1,"purpose":"wiring"},{"ref":"U3","part_id":"tcrt5000-line-sensor","qty":1,"purpose":"left line sensor"},{"ref":"U4","part_id":"tcrt5000-line-sensor","qty":1,"purpose":"right line sensor"}],"connections":[{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U2","pin":"12V"}},{"from":{"ref":"B1","pin":"+"},"to":{"ref":"U1","pin":"VIN"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D5"},"to":{"ref":"U2","pin":"ENA"}},{"from":{"ref":"U1","pin":"D7"},"to":{"ref":"U2","pin":"IN1"}},{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"U2","pin":"IN2"}},{"from":{"ref":"U1","pin":"D11"},"to":{"ref":"U2","pin":"IN3"}},{"from":{"ref":"U1","pin":"D12"},"to":{"ref":"U2","pin":"IN4"}},{"from":{"ref":"U1","pin":"D6"},"to":{"ref":"U2","pin":"ENB"}},{"from":{"ref":"U2","pin":"OUT1"},"to":{"ref":"M1","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT2"},"to":{"ref":"M1","pin":"M-"}},{"from":{"ref":"U2","pin":"OUT3"},"to":{"ref":"M2","pin":"M+"}},{"from":{"ref":"U2","pin":"OUT4"},"to":{"ref":"M2","pin":"M-"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U3","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U3","pin":"DO"},"to":{"ref":"U1","pin":"D2"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U4","pin":"VCC"}},{"from":{"ref":"U4","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U4","pin":"DO"},"to":{"ref":"U1","pin":"D3"}}],"steps":["Screw the two TT motors, wheels and caster onto the chassis.","Mount the Uno, the L298N and the 2×18650 battery holder on the chassis.","Wire the left motor to L298N OUT1/OUT2 and the right motor to OUT3/OUT4.","Battery + to L298N 12V and to Uno VIN; battery − to L298N GND, and L298N GND to Uno GND (common ground).","Remove the ENA/ENB jumpers on the L298N, then wire ENA→5, IN1→7, IN2→8, IN3→11, IN4→12, ENB→6.","Mount both TCRT5000 sensors under the front, about 1 cm above the floor and 2 cm apart.","Sensors: VCC→5V, GND→GND, left DO→pin 2, right DO→pin 3.","Adjust each sensor''s potentiometer so its LED changes over the black line."],"code":{"filename":"line_follower.ino","source":"const int ENA = 5, IN1 = 7, IN2 = 8, IN3 = 11, IN4 = 12, ENB = 6;\n\nvoid drive(int l1, int l2, int r1, int r2) {\n  digitalWrite(IN1, l1); digitalWrite(IN2, l2);\n  digitalWrite(IN3, r1); digitalWrite(IN4, r2);\n}\nvoid forward()  { drive(HIGH, LOW, HIGH, LOW); }\nvoid backward() { drive(LOW, HIGH, LOW, HIGH); }\nvoid left()     { drive(LOW, HIGH, HIGH, LOW); }\nvoid right()    { drive(HIGH, LOW, LOW, HIGH); }\nvoid stopCar()  { drive(LOW, LOW, LOW, LOW); }\n\nvoid setupMotors(int speed) {\n  int pins[] = {ENA, IN1, IN2, IN3, IN4, ENB};\n  for (int p : pins) pinMode(p, OUTPUT);\n  analogWrite(ENA, speed);\n  analogWrite(ENB, speed);\n  stopCar();\n}\n\nconst int LEFT_SENSOR = 2, RIGHT_SENSOR = 3;  // HIGH = black line under the sensor\n\nvoid setup() {\n  setupMotors(150);\n  pinMode(LEFT_SENSOR, INPUT);\n  pinMode(RIGHT_SENSOR, INPUT);\n}\n\nvoid loop() {\n  bool l = digitalRead(LEFT_SENSOR) == HIGH;\n  bool r = digitalRead(RIGHT_SENSOR) == HIGH;\n  if (l && r) stopCar();\n  else if (l) left();\n  else if (r) right();\n  else forward();\n}\n"},"libraries":[],"safety_notes":["Use protected 18650 cells, insert them with the correct polarity, and never short the battery leads.","Lift the wheels off the table for the first test."],"reference_project_id":"line-follower-uno"}'::jsonb),
  ('stepper-28byj48-uno', 'Geared Stepper Motor', array['stepper motor', 'rotate a motor precisely', '28BYJ-48 project', 'turn a dial slowly']::text[], '{"title":"Geared Stepper Motor","summary":"A 28BYJ-48 stepper turns one full revolution each way through a ULN2003 driver.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"uln2003-stepper-driver-board","qty":1,"purpose":"stepper driver"},{"ref":"M1","part_id":"stepper-28byj-48","qty":1,"purpose":"motor"}],"connections":[{"from":{"ref":"U1","pin":"D8"},"to":{"ref":"U2","pin":"IN1"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"U2","pin":"IN2"}},{"from":{"ref":"U1","pin":"D10"},"to":{"ref":"U2","pin":"IN3"}},{"from":{"ref":"U1","pin":"D11"},"to":{"ref":"U2","pin":"IN4"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"+"}},{"from":{"ref":"U2","pin":"-"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"OUT1"},"to":{"ref":"M1","pin":"A"}},{"from":{"ref":"U2","pin":"OUT2"},"to":{"ref":"M1","pin":"B"}},{"from":{"ref":"U2","pin":"OUT3"},"to":{"ref":"M1","pin":"C"}},{"from":{"ref":"U2","pin":"OUT4"},"to":{"ref":"M1","pin":"D"}},{"from":{"ref":"U2","pin":"+"},"to":{"ref":"M1","pin":"VCC"}}],"steps":["Plug the stepper''s 5-wire connector into the ULN2003 board.","Connect ULN2003 IN1–IN4 to pins 8–11.","Connect ULN2003 + to 5V and − to GND.","Upload the sketch."],"code":{"filename":"stepper.ino","source":"#include <Stepper.h>\n\nconst int STEPS_PER_REV = 2048;\nStepper stepper(STEPS_PER_REV, 8, 10, 9, 11);  // IN1, IN3, IN2, IN4 order for 28BYJ-48\n\nvoid setup() {\n  stepper.setSpeed(10);  // rpm\n}\n\nvoid loop() {\n  stepper.step(STEPS_PER_REV);\n  delay(500);\n  stepper.step(-STEPS_PER_REV);\n  delay(500);\n}\n"},"libraries":[{"name":"Stepper","install_hint":"Built into the Arduino IDE"}],"safety_notes":[],"reference_project_id":"stepper-28byj48-uno"}'::jsonb),
  ('nema17-a4988-uno', 'NEMA 17 Stepper with A4988', array['NEMA 17 stepper', '3D printer motor', 'big stepper motor', 'A4988 driver project']::text[], '{"title":"NEMA 17 Stepper with A4988","summary":"Drives a NEMA 17 stepper back and forth from a 12 V adapter through an A4988.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"external","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"a4988-stepper-driver","qty":1,"purpose":"stepper driver"},{"ref":"M1","part_id":"nema17-stepper-motor","qty":1,"purpose":"motor"},{"ref":"PS1","part_id":"dc-adapter-12v-2a","qty":1,"purpose":"12 V motor supply"},{"ref":"C1","part_id":"capacitor-100uf-25v","qty":1,"purpose":"decouples VMOT"}],"connections":[{"from":{"ref":"PS1","pin":"+"},"to":{"ref":"U2","pin":"VMOT"}},{"from":{"ref":"PS1","pin":"-"},"to":{"ref":"U2","pin":"GND"}},{"from":{"ref":"PS1","pin":"+"},"to":{"ref":"U1","pin":"VIN"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VDD"}},{"from":{"ref":"U1","pin":"GND"},"to":{"ref":"U2","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D3"},"to":{"ref":"U2","pin":"STEP"}},{"from":{"ref":"U1","pin":"D4"},"to":{"ref":"U2","pin":"DIR"}},{"from":{"ref":"U2","pin":"RESET"},"to":{"ref":"U2","pin":"SLEEP"}},{"from":{"ref":"U2","pin":"1A"},"to":{"ref":"M1","pin":"A+"}},{"from":{"ref":"U2","pin":"1B"},"to":{"ref":"M1","pin":"A-"}},{"from":{"ref":"U2","pin":"2A"},"to":{"ref":"M1","pin":"B+"}},{"from":{"ref":"U2","pin":"2B"},"to":{"ref":"M1","pin":"B-"}},{"from":{"ref":"C1","pin":"+"},"to":{"ref":"U2","pin":"VMOT"}},{"from":{"ref":"C1","pin":"-"},"to":{"ref":"U2","pin":"GND"}}],"steps":["Set the A4988 current limit to about 1 A (Vref ≈ 0.8 V on most boards) before connecting the motor.","Place a 100 µF capacitor across VMOT and GND, close to the driver.","12 V adapter + to VMOT and Uno VIN; adapter − to driver GND. Uno 5V to VDD and Uno GND to the logic GND.","Connect STEP→pin 3, DIR→pin 4 and tie RESET to SLEEP.","Connect the motor coils: 1A/1B to one coil, 2A/2B to the other.","Upload the sketch."],"code":{"filename":"nema17.ino","source":"const int STEP = 3, DIR = 4;\nconst int STEPS_PER_REV = 200;\n\nvoid move(int steps, bool cw) {\n  digitalWrite(DIR, cw ? HIGH : LOW);\n  for (int i = 0; i < steps; i++) {\n    digitalWrite(STEP, HIGH); delayMicroseconds(800);\n    digitalWrite(STEP, LOW);  delayMicroseconds(800);\n  }\n}\n\nvoid setup() {\n  pinMode(STEP, OUTPUT);\n  pinMode(DIR, OUTPUT);\n}\n\nvoid loop() {\n  move(STEPS_PER_REV, true);\n  delay(500);\n  move(STEPS_PER_REV, false);\n  delay(500);\n}\n"},"libraries":[],"safety_notes":["Never connect or disconnect the motor while the driver is powered — it destroys the A4988.","The driver and motor get hot; add the heatsink."],"reference_project_id":"nema17-a4988-uno"}'::jsonb),
  ('joystick-pan-tilt-uno', 'Joystick Pan-Tilt', array['pan tilt camera mount', 'control two servos with a joystick', 'joystick servo']::text[], '{"title":"Joystick Pan-Tilt","summary":"A joystick moves two servos (pan and tilt). Servos run from a separate 4×AA pack.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"J1","part_id":"joystick-ky023","qty":1,"purpose":"input"},{"ref":"M1","part_id":"sg90-micro-servo","qty":1,"purpose":"pan"},{"ref":"M2","part_id":"sg90-micro-servo","qty":1,"purpose":"tilt"},{"ref":"B1","part_id":"battery-holder-4xaa","qty":1,"purpose":"servo power"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"J1","pin":"+5V"}},{"from":{"ref":"J1","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"J1","pin":"VRx"},"to":{"ref":"U1","pin":"A0"}},{"from":{"ref":"J1","pin":"VRy"},"to":{"ref":"U1","pin":"A1"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"M1","pin":"PWM"}},{"from":{"ref":"U1","pin":"D10"},"to":{"ref":"M2","pin":"PWM"}},{"from":{"ref":"B1","pin":"+"},"to":{"ref":"M1","pin":"V+"}},{"from":{"ref":"B1","pin":"+"},"to":{"ref":"M2","pin":"V+"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"M1","pin":"GND"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"M2","pin":"GND"}},{"from":{"ref":"B1","pin":"-"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["Joystick: +5V→5V, GND→GND, VRx→A0, VRy→A1.","Servo signals to pins 9 (pan) and 10 (tilt).","Power both servos from the 4×AA pack (red to +, brown to −) and connect the pack − to Uno GND.","Upload the sketch."],"code":{"filename":"pan_tilt.ino","source":"#include <Servo.h>\n\nServo pan, tilt;\n\nvoid setup() {\n  pan.attach(9);\n  tilt.attach(10);\n}\n\nvoid loop() {\n  pan.write(map(analogRead(A0), 0, 1023, 0, 180));\n  tilt.write(map(analogRead(A1), 0, 1023, 20, 160));\n  delay(20);\n}\n"},"libraries":[{"name":"Servo","install_hint":"Built into the Arduino IDE"}],"safety_notes":["Use fresh AA cells; never power servos from the Uno''s 5V pin when two are moving."],"reference_project_id":"joystick-pan-tilt-uno"}'::jsonb),
  ('weather-station-lcd-uno', 'Weather Station with LCD', array['weather station', 'show temperature and humidity on a screen', 'thermometer with LCD']::text[], '{"title":"Weather Station with LCD","summary":"Shows temperature and humidity from a DHT22 on a 16×2 I2C LCD.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"dht22-sensor","qty":1,"purpose":"temperature/humidity"},{"ref":"R1","part_id":"resistor-10k","qty":1,"purpose":"DHT22 data pull-up"},{"ref":"U3","part_id":"lcd1602-i2c","qty":1,"purpose":"display"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"DATA"},"to":{"ref":"U1","pin":"D2"}},{"from":{"ref":"R1","pin":"1"},"to":{"ref":"U2","pin":"DATA"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"U1","pin":"5V"}},{"from":{"ref":"U1","pin":"A4"},"to":{"ref":"U3","pin":"SDA"}},{"from":{"ref":"U1","pin":"A5"},"to":{"ref":"U3","pin":"SCL"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U3","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["DHT22: VCC→5V, GND→GND, DATA→pin 2, plus a 10 kΩ resistor from DATA to 5V.","LCD backpack: SDA→A4, SCL→A5, VCC→5V, GND→GND.","Install the libraries, upload, and adjust the backpack''s contrast trimmer if the screen is blank."],"code":{"filename":"weather_lcd.ino","source":"#include <DHT.h>\n#include <LiquidCrystal_I2C.h>\n\nDHT dht(2, DHT22);\nLiquidCrystal_I2C lcd(0x27, 16, 2);  // try 0x3F if nothing shows\n\nvoid setup() {\n  dht.begin();\n  lcd.init();\n  lcd.backlight();\n}\n\nvoid loop() {\n  float t = dht.readTemperature();\n  float h = dht.readHumidity();\n  lcd.clear();\n  if (isnan(t) || isnan(h)) {\n    lcd.print(\"Sensor error\");\n  } else {\n    lcd.print(\"Temp: \"); lcd.print(t, 1); lcd.print(\" C\");\n    lcd.setCursor(0, 1);\n    lcd.print(\"Hum:  \"); lcd.print(h, 0); lcd.print(\" %\");\n  }\n  delay(2000);\n}\n"},"libraries":[{"name":"DHT sensor library","install_hint":"Library Manager: DHT sensor library by Adafruit (+ Adafruit Unified Sensor)"},{"name":"LiquidCrystal I2C","install_hint":"Library Manager: LiquidCrystal I2C by Frank de Brabander"}],"safety_notes":[],"reference_project_id":"weather-station-lcd-uno"}'::jsonb),
  ('oled-thermometer-esp32', 'OLED Thermometer (ESP32)', array['ESP32 thermometer', 'temperature on an OLED', 'small screen weather display']::text[], '{"title":"OLED Thermometer (ESP32)","summary":"An ESP32 shows DHT22 temperature and humidity on a 0.96\" OLED, everything at 3.3 V.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"esp32-devkit-v1","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"dht22-sensor","qty":1,"purpose":"temperature/humidity"},{"ref":"R1","part_id":"resistor-10k","qty":1,"purpose":"DHT22 data pull-up"},{"ref":"U3","part_id":"oled-ssd1306-128x64-i2c","qty":1,"purpose":"display"}],"connections":[{"from":{"ref":"U1","pin":"3V3"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"DATA"},"to":{"ref":"U1","pin":"D4"}},{"from":{"ref":"R1","pin":"1"},"to":{"ref":"U2","pin":"DATA"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"U1","pin":"3V3"}},{"from":{"ref":"U1","pin":"3V3"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U3","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D21"},"to":{"ref":"U3","pin":"SDA"}},{"from":{"ref":"U1","pin":"D22"},"to":{"ref":"U3","pin":"SCL"}}],"steps":["Power the DHT22 and the OLED from the ESP32 3V3 pin (not VIN — the ESP32 pins are not 5 V tolerant).","DHT22 DATA→D4 with a 10 kΩ pull-up to 3V3.","OLED SDA→D21, SCL→D22.","Install the libraries and upload."],"code":{"filename":"oled_thermo.ino","source":"#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n#include <DHT.h>\n\nAdafruit_SSD1306 display(128, 64, &Wire, -1);\nDHT dht(4, DHT22);\n\nvoid setup() {\n  Wire.begin(21, 22);\n  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);\n  dht.begin();\n}\n\nvoid loop() {\n  float t = dht.readTemperature(), h = dht.readHumidity();\n  display.clearDisplay();\n  display.setTextColor(SSD1306_WHITE);\n  display.setTextSize(2);\n  display.setCursor(0, 8);\n  if (isnan(t)) {\n    display.print(\"No sensor\");\n  } else {\n    display.print(t, 1); display.println(\" C\");\n    display.print(h, 0); display.println(\" %\");\n  }\n  display.display();\n  delay(2000);\n}\n"},"libraries":[{"name":"Adafruit SSD1306","install_hint":"Library Manager (installs Adafruit GFX too)"},{"name":"DHT sensor library","install_hint":"Library Manager: DHT sensor library by Adafruit"}],"safety_notes":[],"reference_project_id":"oled-thermometer-esp32"}'::jsonb),
  ('plant-watering-uno', 'Automatic Plant Watering', array['water my plants automatically', 'plant watering system', 'soil moisture pump']::text[], '{"title":"Automatic Plant Watering","summary":"When the soil is dry, a relay runs a small pump for 3 seconds.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"soil-moisture-capacitive-v1-2","qty":1,"purpose":"soil sensor"},{"ref":"K1","part_id":"relay-module-5v-1ch","qty":1,"purpose":"switches the pump"},{"ref":"P1","part_id":"mini-water-pump-5v","qty":1,"purpose":"pump"},{"ref":"B1","part_id":"battery-holder-4xaa","qty":1,"purpose":"pump power"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"AOUT"},"to":{"ref":"U1","pin":"A0"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"K1","pin":"VCC"}},{"from":{"ref":"K1","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D7"},"to":{"ref":"K1","pin":"IN"}},{"from":{"ref":"B1","pin":"+"},"to":{"ref":"K1","pin":"COM"}},{"from":{"ref":"K1","pin":"NO"},"to":{"ref":"P1","pin":"+"}},{"from":{"ref":"P1","pin":"-"},"to":{"ref":"B1","pin":"-"}}],"steps":["Push the soil sensor into the pot up to the line; VCC→5V, GND→GND, AOUT→A0.","Relay module: VCC→5V, GND→GND, IN→pin 7.","Pump circuit: battery + → relay COM, relay NO → pump +, pump − → battery −.","Put the pump in a water container and the tube in the pot; upload the sketch.","Read the dry/wet values in the Serial Monitor and adjust DRY_LEVEL."],"code":{"filename":"plant_watering.ino","source":"const int SENSOR = A0, RELAY = 7;\nconst int DRY_LEVEL = 520;  // capacitive sensors read HIGHER when dry\n\nvoid setup() {\n  pinMode(RELAY, OUTPUT);\n  digitalWrite(RELAY, LOW);\n  Serial.begin(9600);\n}\n\nvoid loop() {\n  int moisture = analogRead(SENSOR);\n  Serial.println(moisture);\n  if (moisture > DRY_LEVEL) {\n    digitalWrite(RELAY, HIGH);\n    delay(3000);\n    digitalWrite(RELAY, LOW);\n    delay(60000UL);  // let the water soak in\n  }\n  delay(1000);\n}\n"},"libraries":[],"safety_notes":["Keep water away from the Uno and relay; mount electronics above the water container."],"reference_project_id":"plant-watering-uno"}'::jsonb),
  ('neopixel-ring-uno', 'NeoPixel Rainbow Ring', array['RGB light effects', 'rainbow LEDs', 'NeoPixel project', 'color changing lamp']::text[], '{"title":"NeoPixel Rainbow Ring","summary":"A 12-LED WS2812B ring shows a moving rainbow.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"L1","part_id":"neopixel-ring-12","qty":1,"purpose":"LEDs"},{"ref":"R1","part_id":"resistor-330","qty":1,"purpose":"data line resistor"},{"ref":"C1","part_id":"capacitor-100uf-25v","qty":1,"purpose":"smooths LED power"}],"connections":[{"from":{"ref":"U1","pin":"D6"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"L1","pin":"DIN"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"L1","pin":"VCC"}},{"from":{"ref":"L1","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"C1","pin":"+"},"to":{"ref":"U1","pin":"5V"}},{"from":{"ref":"C1","pin":"-"},"to":{"ref":"U1","pin":"GND"}}],"steps":["Ring VCC→5V and GND→GND; put the 100 µF capacitor across 5V/GND (stripe = −).","Pin 6 → 330 Ω → ring DIN.","Install Adafruit NeoPixel and upload. Brightness is capped at 40% to stay within USB power."],"code":{"filename":"rainbow_ring.ino","source":"#include <Adafruit_NeoPixel.h>\n\nAdafruit_NeoPixel ring(12, 6, NEO_GRB + NEO_KHZ800);\n\nvoid setup() {\n  ring.begin();\n  ring.setBrightness(100);  // of 255\n}\n\nvoid loop() {\n  static uint16_t hue = 0;\n  for (int i = 0; i < 12; i++) {\n    ring.setPixelColor(i, ring.gamma32(ring.ColorHSV(hue + i * 65536L / 12)));\n  }\n  ring.show();\n  hue += 256;\n  delay(20);\n}\n"},"libraries":[{"name":"Adafruit NeoPixel","install_hint":"Library Manager: Adafruit NeoPixel"}],"safety_notes":[],"reference_project_id":"neopixel-ring-uno"}'::jsonb),
  ('rfid-door-lock-esp32', 'RFID Door Lock (ESP32)', array['RFID door lock', 'unlock with a card', 'NFC access control', 'RC522 project']::text[], '{"title":"RFID Door Lock (ESP32)","summary":"An authorised RFID card turns a servo latch and lights the green LED; others light red.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"esp32-devkit-v1","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"rfid-rc522","qty":1,"purpose":"card reader"},{"ref":"M1","part_id":"sg90-micro-servo","qty":1,"purpose":"latch"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"green LED resistor"},{"ref":"R2","part_id":"resistor-220","qty":1,"purpose":"red LED resistor"},{"ref":"D1","part_id":"led-5mm-green","qty":1,"purpose":"access granted"},{"ref":"D2","part_id":"led-5mm-red","qty":1,"purpose":"access denied"}],"connections":[{"from":{"ref":"U1","pin":"3V3"},"to":{"ref":"U2","pin":"3.3V"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D5"},"to":{"ref":"U2","pin":"SDA"}},{"from":{"ref":"U1","pin":"D18"},"to":{"ref":"U2","pin":"SCK"}},{"from":{"ref":"U1","pin":"D23"},"to":{"ref":"U2","pin":"MOSI"}},{"from":{"ref":"U2","pin":"MISO"},"to":{"ref":"U1","pin":"D19"}},{"from":{"ref":"U1","pin":"D4"},"to":{"ref":"U2","pin":"RST"}},{"from":{"ref":"U1","pin":"D13"},"to":{"ref":"M1","pin":"PWM"}},{"from":{"ref":"U1","pin":"VIN"},"to":{"ref":"M1","pin":"V+"}},{"from":{"ref":"M1","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D25"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D26"},"to":{"ref":"R2","pin":"1"}},{"from":{"ref":"R2","pin":"2"},"to":{"ref":"D2","pin":"A"}},{"from":{"ref":"D2","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["RC522: 3.3V→3V3 (never 5 V), GND→GND, SDA→D5, SCK→D18, MOSI→D23, MISO→D19, RST→D4.","Servo: signal→D13, red→VIN (5 V from USB), brown→GND.","LEDs via 220 Ω: green→D25, red→D26.","Upload, open the Serial Monitor, scan your card and paste its UID into ALLOWED_UID."],"code":{"filename":"rfid_lock.ino","source":"#include <SPI.h>\n#include <MFRC522.h>\n#include <ESP32Servo.h>\n\nconst int SS_PIN = 5, RST_PIN = 4, SERVO_PIN = 13, GREEN = 25, RED = 26;\nconst String ALLOWED_UID = \"DE AD BE EF\";  // replace with your card''s UID\n\nMFRC522 rfid(SS_PIN, RST_PIN);\nServo latch;\n\nString uidString() {\n  String s;\n  for (byte i = 0; i < rfid.uid.size; i++) {\n    if (i) s += \" \";\n    if (rfid.uid.uidByte[i] < 0x10) s += \"0\";\n    s += String(rfid.uid.uidByte[i], HEX);\n  }\n  s.toUpperCase();\n  return s;\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  SPI.begin();\n  rfid.PCD_Init();\n  latch.attach(SERVO_PIN);\n  latch.write(0);\n  pinMode(GREEN, OUTPUT);\n  pinMode(RED, OUTPUT);\n}\n\nvoid loop() {\n  if (!rfid.PICC_IsNewCardPresent() || !rfid.PICC_ReadCardSerial()) return;\n  String uid = uidString();\n  Serial.println(uid);\n  bool ok = uid == ALLOWED_UID;\n  digitalWrite(ok ? GREEN : RED, HIGH);\n  if (ok) { latch.write(90); delay(3000); latch.write(0); } else { delay(1000); }\n  digitalWrite(GREEN, LOW);\n  digitalWrite(RED, LOW);\n  rfid.PICC_HaltA();\n}\n"},"libraries":[{"name":"MFRC522","install_hint":"Library Manager: MFRC522 by GithubCommunity"},{"name":"ESP32Servo","install_hint":"Library Manager: ESP32Servo by Kevin Harrington"}],"safety_notes":["A hobby servo latch is not a security device; do not rely on it for a real door."],"reference_project_id":"rfid-door-lock-esp32"}'::jsonb),
  ('keypad-lock-uno', 'Keypad Code Lock', array['password lock', 'keypad door lock', 'enter a code to open', 'safe with a keypad']::text[], '{"title":"Keypad Code Lock","summary":"Typing the right 4-digit code on a keypad opens a servo latch.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"KP1","part_id":"membrane-keypad-4x4","qty":1,"purpose":"code entry"},{"ref":"M1","part_id":"sg90-micro-servo","qty":1,"purpose":"latch"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"green LED resistor"},{"ref":"R2","part_id":"resistor-220","qty":1,"purpose":"red LED resistor"},{"ref":"D1","part_id":"led-5mm-green","qty":1,"purpose":"open"},{"ref":"D2","part_id":"led-5mm-red","qty":1,"purpose":"locked"}],"connections":[{"from":{"ref":"KP1","pin":"R1"},"to":{"ref":"U1","pin":"D9"}},{"from":{"ref":"KP1","pin":"R2"},"to":{"ref":"U1","pin":"D8"}},{"from":{"ref":"KP1","pin":"R3"},"to":{"ref":"U1","pin":"D7"}},{"from":{"ref":"KP1","pin":"R4"},"to":{"ref":"U1","pin":"D6"}},{"from":{"ref":"KP1","pin":"C1"},"to":{"ref":"U1","pin":"D5"}},{"from":{"ref":"KP1","pin":"C2"},"to":{"ref":"U1","pin":"D4"}},{"from":{"ref":"KP1","pin":"C3"},"to":{"ref":"U1","pin":"D3"}},{"from":{"ref":"KP1","pin":"C4"},"to":{"ref":"U1","pin":"D2"}},{"from":{"ref":"U1","pin":"D10"},"to":{"ref":"M1","pin":"PWM"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"M1","pin":"V+"}},{"from":{"ref":"M1","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D12"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"D13"},"to":{"ref":"R2","pin":"1"}},{"from":{"ref":"R2","pin":"2"},"to":{"ref":"D2","pin":"A"}},{"from":{"ref":"D2","pin":"C"},"to":{"ref":"U1","pin":"GND.2"}}],"steps":["Keypad rows R1–R4 → pins 9–6, columns C1–C4 → pins 5–2.","Servo signal→10, red→5V, brown→GND.","Green LED via 220 Ω → 12, red LED via 220 Ω → 13.","Install the Keypad library, upload, and type 1234 then #."],"code":{"filename":"keypad_lock.ino","source":"#include <Keypad.h>\n#include <Servo.h>\n\nconst byte ROWS = 4, COLS = 4;\nchar keys[ROWS][COLS] = {{''1'',''2'',''3'',''A''},{''4'',''5'',''6'',''B''},{''7'',''8'',''9'',''C''},{''*'',''0'',''#'',''D''}};\nbyte rowPins[ROWS] = {9, 8, 7, 6};\nbyte colPins[COLS] = {5, 4, 3, 2};\nKeypad keypad = Keypad(makeKeymap(keys), rowPins, colPins, ROWS, COLS);\nServo latch;\nconst String CODE = \"1234\";\nString entered;\n\nvoid setup() {\n  latch.attach(10);\n  latch.write(0);\n  pinMode(12, OUTPUT);\n  pinMode(13, OUTPUT);\n  digitalWrite(13, HIGH);\n}\n\nvoid loop() {\n  char k = keypad.getKey();\n  if (!k) return;\n  if (k == ''#'') {\n    bool ok = entered == CODE;\n    entered = \"\";\n    if (ok) {\n      digitalWrite(13, LOW); digitalWrite(12, HIGH);\n      latch.write(90); delay(4000); latch.write(0);\n      digitalWrite(12, LOW); digitalWrite(13, HIGH);\n    }\n  } else if (k == ''*'') {\n    entered = \"\";\n  } else if (entered.length() < 8) {\n    entered += k;\n  }\n}\n"},"libraries":[{"name":"Keypad","install_hint":"Library Manager: Keypad by Mark Stanley, Alexander Brevig"},{"name":"Servo","install_hint":"Built into the Arduino IDE"}],"safety_notes":["A hobby servo latch is not a security device."],"reference_project_id":"keypad-lock-uno"}'::jsonb),
  ('rtc-clock-lcd-uno', 'Desk Clock', array['digital clock', 'show the time on an LCD', 'real time clock project', 'alarm clock']::text[], '{"title":"Desk Clock","summary":"A DS3231 keeps time and a 16×2 LCD shows the date and time (both on the I2C bus).","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"ds3231-rtc","qty":1,"purpose":"clock"},{"ref":"U3","part_id":"lcd1602-i2c","qty":1,"purpose":"display"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"A4"},"to":{"ref":"U2","pin":"SDA"}},{"from":{"ref":"U1","pin":"A5"},"to":{"ref":"U2","pin":"SCL"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U3","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"A4"},"to":{"ref":"U3","pin":"SDA"}},{"from":{"ref":"U1","pin":"A5"},"to":{"ref":"U3","pin":"SCL"}}],"steps":["Connect both modules to 5V and GND.","Connect both SDA pins to A4 and both SCL pins to A5 (shared I2C bus).","Install RTClib and LiquidCrystal I2C; upload once to set the time from your computer."],"code":{"filename":"desk_clock.ino","source":"#include <RTClib.h>\n#include <LiquidCrystal_I2C.h>\n\nRTC_DS3231 rtc;\nLiquidCrystal_I2C lcd(0x27, 16, 2);\n\nvoid print2(int v) { if (v < 10) lcd.print(''0''); lcd.print(v); }\n\nvoid setup() {\n  lcd.init();\n  lcd.backlight();\n  rtc.begin();\n  if (rtc.lostPower()) rtc.adjust(DateTime(F(__DATE__), F(__TIME__)));\n}\n\nvoid loop() {\n  DateTime now = rtc.now();\n  lcd.setCursor(0, 0);\n  print2(now.day()); lcd.print(''/''); print2(now.month()); lcd.print(''/''); lcd.print(now.year());\n  lcd.setCursor(0, 1);\n  print2(now.hour()); lcd.print('':''); print2(now.minute()); lcd.print('':''); print2(now.second());\n  delay(250);\n}\n"},"libraries":[{"name":"RTClib","install_hint":"Library Manager: RTClib by Adafruit"},{"name":"LiquidCrystal I2C","install_hint":"Library Manager: LiquidCrystal I2C by Frank de Brabander"}],"safety_notes":[],"reference_project_id":"rtc-clock-lcd-uno"}'::jsonb),
  ('temperature-fan-uno', 'Temperature-Controlled Fan', array['fan turns on when hot', 'automatic cooling fan', 'temperature controlled fan', 'MOSFET fan control']::text[], '{"title":"Temperature-Controlled Fan","summary":"A MOSFET switches a 5 V fan on above 28 °C, measured by a DS18B20.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"arduino-uno-r3","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"ds18b20-waterproof","qty":1,"purpose":"temperature"},{"ref":"R1","part_id":"resistor-4k7","qty":1,"purpose":"1-Wire pull-up"},{"ref":"Q1","part_id":"irlz44n-mosfet","qty":1,"purpose":"switches the fan"},{"ref":"R2","part_id":"resistor-220","qty":1,"purpose":"gate resistor"},{"ref":"F1","part_id":"dc-fan-5v-40mm","qty":1,"purpose":"fan"},{"ref":"D1","part_id":"diode-1n4007","qty":1,"purpose":"flyback protection"}],"connections":[{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"U2","pin":"VDD"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"DQ"},"to":{"ref":"U1","pin":"D2"}},{"from":{"ref":"R1","pin":"1"},"to":{"ref":"U2","pin":"DQ"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"U1","pin":"5V"}},{"from":{"ref":"U1","pin":"D9"},"to":{"ref":"R2","pin":"1"}},{"from":{"ref":"R2","pin":"2"},"to":{"ref":"Q1","pin":"G"}},{"from":{"ref":"Q1","pin":"S"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"5V"},"to":{"ref":"F1","pin":"+"}},{"from":{"ref":"F1","pin":"-"},"to":{"ref":"Q1","pin":"D"}},{"from":{"ref":"D1","pin":"K"},"to":{"ref":"F1","pin":"+"}},{"from":{"ref":"D1","pin":"A"},"to":{"ref":"F1","pin":"-"}}],"steps":["DS18B20: red→5V, black→GND, yellow→pin 2, with a 4.7 kΩ resistor between yellow and 5V.","MOSFET (flat side facing you: G, D, S): G via 220 Ω to pin 9, S to GND.","Fan red → 5V, fan black → MOSFET drain.","Put the 1N4007 across the fan: striped end (K) to fan +, other end to fan −.","Install OneWire and DallasTemperature, then upload."],"code":{"filename":"temp_fan.ino","source":"#include <OneWire.h>\n#include <DallasTemperature.h>\n\nOneWire bus(2);\nDallasTemperature sensors(&bus);\nconst int FAN = 9;\nconst float ON_AT = 28.0, OFF_AT = 26.0;  // hysteresis\nbool fanOn = false;\n\nvoid setup() {\n  pinMode(FAN, OUTPUT);\n  sensors.begin();\n}\n\nvoid loop() {\n  sensors.requestTemperatures();\n  float c = sensors.getTempCByIndex(0);\n  if (c != DEVICE_DISCONNECTED_C) {\n    if (!fanOn && c >= ON_AT) fanOn = true;\n    if (fanOn && c <= OFF_AT) fanOn = false;\n  }\n  digitalWrite(FAN, fanOn ? HIGH : LOW);\n  delay(1000);\n}\n"},"libraries":[{"name":"OneWire","install_hint":"Library Manager: OneWire"},{"name":"DallasTemperature","install_hint":"Library Manager: DallasTemperature by Miles Burton"}],"safety_notes":["Always fit the flyback diode across motor/fan loads switched by a MOSFET."],"reference_project_id":"temperature-fan-uno"}'::jsonb),
  ('esp32-web-barometer', 'Wi-Fi Barometer (ESP32)', array['IoT weather station', 'see temperature on my phone', 'wifi sensor web page', 'barometer']::text[], '{"title":"Wi-Fi Barometer (ESP32)","summary":"The ESP32 serves a web page with BMP280 temperature and air pressure on your Wi-Fi.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"esp32-devkit-v1","qty":1,"purpose":"controller + Wi-Fi"},{"ref":"U2","part_id":"bmp280-3v3-module","qty":1,"purpose":"pressure/temperature"}],"connections":[{"from":{"ref":"U1","pin":"3V3"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D21"},"to":{"ref":"U2","pin":"SDA"}},{"from":{"ref":"U1","pin":"D22"},"to":{"ref":"U2","pin":"SCL"}}],"steps":["BMP280: VCC→3V3 (3.3 V only), GND→GND, SDA→D21, SCL→D22.","Put your Wi-Fi name and password into the sketch and upload.","Open the IP address printed in the Serial Monitor (115200 baud)."],"code":{"filename":"web_barometer.ino","source":"#include <WiFi.h>\n#include <WebServer.h>\n#include <Adafruit_BMP280.h>\n\nconst char* SSID = \"your-wifi\";\nconst char* PASS = \"your-password\";\nWebServer server(80);\nAdafruit_BMP280 bmp;\n\nvoid handleRoot() {\n  String page = \"<meta name=viewport content=''width=device-width''><meta http-equiv=refresh content=10>\";\n  page += \"<h1>\" + String(bmp.readTemperature(), 1) + \" &deg;C</h1>\";\n  page += \"<h2>\" + String(bmp.readPressure() / 100.0, 1) + \" hPa</h2>\";\n  server.send(200, \"text/html\", page);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin(21, 22);\n  bmp.begin(0x76);\n  WiFi.begin(SSID, PASS);\n  while (WiFi.status() != WL_CONNECTED) delay(300);\n  Serial.println(WiFi.localIP());\n  server.on(\"/\", handleRoot);\n  server.begin();\n}\n\nvoid loop() {\n  server.handleClient();\n}\n"},"libraries":[{"name":"Adafruit BMP280","install_hint":"Library Manager: Adafruit BMP280 Library"}],"safety_notes":[],"reference_project_id":"esp32-web-barometer"}'::jsonb),
  ('nodemcu-wifi-fan-switch', 'Wi-Fi Fan Switch (ESP8266)', array['turn something on over wifi', 'smart switch', 'wifi relay', 'control a fan from my phone']::text[], '{"title":"Wi-Fi Fan Switch (ESP8266)","summary":"A NodeMCU web page switches a relay that powers a 5 V fan from its own adapter.","feasibility":"achievable","closest_reason":null,"language":"arduino_cpp","power_mode":"usb","parts":[{"ref":"U1","part_id":"nodemcu-esp8266-v3","qty":1,"purpose":"controller + Wi-Fi"},{"ref":"K1","part_id":"relay-module-5v-1ch","qty":1,"purpose":"switch"},{"ref":"F1","part_id":"dc-fan-5v-40mm","qty":1,"purpose":"load"},{"ref":"PS1","part_id":"dc-adapter-5v-2a","qty":1,"purpose":"fan power"}],"connections":[{"from":{"ref":"U1","pin":"VIN"},"to":{"ref":"K1","pin":"VCC"}},{"from":{"ref":"K1","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U1","pin":"D1"},"to":{"ref":"K1","pin":"IN"}},{"from":{"ref":"PS1","pin":"+"},"to":{"ref":"K1","pin":"COM"}},{"from":{"ref":"K1","pin":"NO"},"to":{"ref":"F1","pin":"+"}},{"from":{"ref":"F1","pin":"-"},"to":{"ref":"PS1","pin":"-"}}],"steps":["Relay module: VCC→NodeMCU VIN (5 V from USB), GND→GND, IN→D1.","Fan circuit: adapter + → relay COM, relay NO → fan +, fan − → adapter −.","Enter your Wi-Fi details, upload, and open the printed IP address."],"code":{"filename":"wifi_switch.ino","source":"#include <ESP8266WiFi.h>\n#include <ESP8266WebServer.h>\n\nconst char* SSID = \"your-wifi\";\nconst char* PASS = \"your-password\";\nconst int RELAY = D1;\nESP8266WebServer server(80);\nbool on = false;\n\nvoid page() {\n  server.send(200, \"text/html\",\n    String(\"<meta name=viewport content=''width=device-width''><h1>Fan is \") + (on ? \"ON\" : \"OFF\") +\n    \"</h1><a href=/on>ON</a> | <a href=/off>OFF</a>\");\n}\n\nvoid setup() {\n  pinMode(RELAY, OUTPUT);\n  digitalWrite(RELAY, LOW);\n  Serial.begin(115200);\n  WiFi.begin(SSID, PASS);\n  while (WiFi.status() != WL_CONNECTED) delay(300);\n  Serial.println(WiFi.localIP());\n  server.on(\"/\", page);\n  server.on(\"/on\", [] { on = true; digitalWrite(RELAY, HIGH); page(); });\n  server.on(\"/off\", [] { on = false; digitalWrite(RELAY, LOW); page(); });\n  server.begin();\n}\n\nvoid loop() {\n  server.handleClient();\n}\n"},"libraries":[{"name":"ESP8266 board package","install_hint":"Boards Manager: esp8266 by ESP8266 Community"}],"safety_notes":["Only switch low-voltage DC loads with this build — never mains."],"reference_project_id":"nodemcu-wifi-fan-switch"}'::jsonb),
  ('pico-blink-micropython', 'Pico Blink (MicroPython)', array['Raspberry Pi Pico first project', 'MicroPython blink', 'Pico LED']::text[], '{"title":"Pico Blink (MicroPython)","summary":"An LED on GP15 blinks using MicroPython.","feasibility":"achievable","closest_reason":null,"language":"micropython","power_mode":"usb","parts":[{"ref":"U1","part_id":"raspberry-pi-pico","qty":1,"purpose":"controller"},{"ref":"R1","part_id":"resistor-220","qty":1,"purpose":"LED resistor"},{"ref":"D1","part_id":"led-5mm-red","qty":1,"purpose":"indicator"}],"connections":[{"from":{"ref":"U1","pin":"GP15"},"to":{"ref":"R1","pin":"1"}},{"from":{"ref":"R1","pin":"2"},"to":{"ref":"D1","pin":"A"}},{"from":{"ref":"D1","pin":"C"},"to":{"ref":"U1","pin":"GND"}}],"steps":["Flash MicroPython onto the Pico (hold BOOTSEL, drag the UF2 file).","GP15 → 220 Ω → LED anode; LED cathode → GND.","Open Thonny, paste the code and save it on the Pico as main.py."],"code":{"filename":"main.py","source":"from machine import Pin\nimport time\n\nled = Pin(15, Pin.OUT)\n\nwhile True:\n    led.toggle()\n    time.sleep(0.5)\n"},"libraries":[],"safety_notes":[],"reference_project_id":"pico-blink-micropython"}'::jsonb),
  ('pico-oled-dht11-micropython', 'Pico Climate Display (MicroPython)', array['Pico temperature display', 'MicroPython OLED', 'humidity monitor Raspberry Pi Pico']::text[], '{"title":"Pico Climate Display (MicroPython)","summary":"A Pico shows DHT11 temperature and humidity on an SSD1306 OLED.","feasibility":"achievable","closest_reason":null,"language":"micropython","power_mode":"usb","parts":[{"ref":"U1","part_id":"raspberry-pi-pico","qty":1,"purpose":"controller"},{"ref":"U2","part_id":"dht11-module","qty":1,"purpose":"temperature/humidity"},{"ref":"U3","part_id":"oled-ssd1306-128x64-i2c","qty":1,"purpose":"display"}],"connections":[{"from":{"ref":"U1","pin":"3V3"},"to":{"ref":"U2","pin":"VCC"}},{"from":{"ref":"U2","pin":"GND"},"to":{"ref":"U1","pin":"GND"}},{"from":{"ref":"U2","pin":"DATA"},"to":{"ref":"U1","pin":"GP16"}},{"from":{"ref":"U1","pin":"3V3"},"to":{"ref":"U3","pin":"VCC"}},{"from":{"ref":"U3","pin":"GND"},"to":{"ref":"U1","pin":"GND.2"}},{"from":{"ref":"U1","pin":"GP4"},"to":{"ref":"U3","pin":"SDA"}},{"from":{"ref":"U1","pin":"GP5"},"to":{"ref":"U3","pin":"SCL"}}],"steps":["DHT11 module: VCC→3V3(OUT), GND→GND, DATA→GP16.","OLED: VCC→3V3(OUT), GND→GND, SDA→GP4, SCL→GP5.","In Thonny run: import mip; mip.install(''ssd1306''). Then save the code as main.py."],"code":{"filename":"main.py","source":"from machine import Pin, I2C\nimport dht\nimport ssd1306\nimport time\n\ni2c = I2C(0, sda=Pin(4), scl=Pin(5), freq=400000)\noled = ssd1306.SSD1306_I2C(128, 64, i2c)\nsensor = dht.DHT11(Pin(16))\n\nwhile True:\n    oled.fill(0)\n    try:\n        sensor.measure()\n        oled.text(\"Temp: %d C\" % sensor.temperature(), 0, 16)\n        oled.text(\"Hum:  %d %%\" % sensor.humidity(), 0, 32)\n    except OSError:\n        oled.text(\"Sensor error\", 0, 24)\n    oled.show()\n    time.sleep(2)\n"},"libraries":[{"name":"ssd1306","install_hint":"MicroPython: import mip; mip.install(''ssd1306'')"}],"safety_notes":[],"reference_project_id":"pico-oled-dht11-micropython"}'::jsonb)
